    new_h, new_w = 3 * h, 2 * w

    output = [[0] * new_w for _ in range(new_h)]

    # Build row permutation based on analysis of demos
    # Pattern appears to be: for 3h rows, cycle through input rows with specific pattern
    # Based on demo analysis: row_map = [h-1, h-2, ..., 0, h-1, h-2, ..., 0, h-1, h-2, ..., 0]

    for r_out in range(new_h):
        # Row mapping: cycle through input rows in reverse order pattern
        if r_out < h:
            r_in = h - 1 - r_out
        elif r_out < 2 * h:
            r_in = h - 1 - (r_out - h)
        else:
            r_in = h - 1 - (r_out - 2 * h)

        # Handle wrap-around for small h
        if r_in < 0:
            r_in = 0

        for c_out in range(new_w):
            # Column mapping: first half of columns direct, second half mirrored
            if c_out < w:
                c_in = c_out
            else:
                c_in = w - 1 - (c_out - w)

            output[r_out][c_out] = grid[r_in][c_in]

    return output
